<template>
  <div class="review-view">
    <header class="page-heading"><div><div class="eyebrow">HUMAN REVIEW</div><h1>人工复核</h1><p>核对低置信度字段、原文证据和业务规则，再确认交付。</p></div><div class="heading-count"><strong>{{ reviews.length }}</strong><span>当前任务</span></div></header>
    <section class="review-shell">
      <aside class="queue-panel">
        <div class="queue-filter"><button v-for="item in filters" :key="item.value" :class="{active:filter===item.value}" @click="setFilter(item.value)">{{ item.label }}</button></div>
        <div v-if="loading" class="queue-state">正在加载...</div>
        <div v-else-if="!reviews.length" class="queue-state"><span class="state-icon">✓</span><strong>没有待处理任务</strong><small>完成信息提取后，结果会自动进入复核队列。</small></div>
        <button v-for="item in reviews" v-else :key="item.id" class="review-item" :class="{selected:selected?.id===item.id}" @click="selectReview(item)">
          <span class="priority-dot" :class="item.priority"></span><span class="review-summary"><strong>{{ item.title }}</strong><small>{{ item.fields.length }} 个字段 · {{ issueCount(item) }} 项提示</small><em>{{ formatDate(item.created_at) }}</em></span><span class="review-status">{{ statusText[item.status] }}</span>
        </button>
      </aside>

      <main class="review-detail">
        <div v-if="!selected" class="detail-empty"><span>⌁</span><strong>选择一项复核任务</strong><p>你可以逐字段检查结果、修正内容并完成审批。</p></div>
        <template v-else>
          <div class="detail-head"><div><span class="breadcrumb">复核任务 / {{ selected.document?.filename || '提取记录' }}</span><h2>{{ selected.title }}</h2></div><span class="status-pill" :class="selected.status">{{ statusText[selected.status] }}</span></div>
          <div class="validation-summary"><div><strong>{{ errorCount }}</strong><span>错误</span></div><div><strong>{{ warningCount }}</strong><span>提示</span></div><p v-if="!errorCount">当前没有阻止审批的规则错误</p><p v-else>请先修正错误字段，再通过复核</p></div>
          <div class="field-list">
            <article v-for="(field,index) in editableFields" :key="`${field.name}-${index}`" class="field-card" :class="fieldLevel(field.name)">
              <div class="field-top"><label>{{ field.name }}</label><span class="confidence" :class="confidenceClass(field.confidence)">置信度 {{ Math.round(field.confidence*100) }}%</span></div>
              <textarea v-if="isLongValue(field.value)" v-model="field.value" @input="field.corrected=true"></textarea><input v-else v-model="field.value" @input="field.corrected=true" />
              <div class="evidence"><span>原文证据</span><p>{{ field.evidence || '模型未返回证据，请人工核对原始文档。' }}</p><small v-if="field.source_page">第 {{ field.source_page }} 页</small></div>
              <div v-for="issue in fieldIssues(field.name)" :key="issue.code" class="issue" :class="issue.level">{{ issue.level==='error'?'!':'i' }} {{ issue.message }}</div>
            </article>
          </div>
          <label class="note"><span>复核说明</span><textarea v-model="note" placeholder="记录修改原因或需要后续关注的信息"></textarea></label>
          <div class="detail-actions"><button class="reject-btn" :disabled="saving" @click="submit('reject')">驳回</button><button class="save-btn" :disabled="saving" @click="submit('save')">保存进度</button><button class="approve-btn" :disabled="saving || errorCount>0" @click="submit('approve')">通过复核</button></div>
        </template>
      </main>
    </section>
  </div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { getReview, getReviews, updateReview } from '../../api/workspace'
const loading=ref(true),saving=ref(false),reviews=ref([]),selected=ref(null),editableFields=ref([]),note=ref(''),filter=ref('pending')
const filters=[{label:'待处理',value:'pending'},{label:'复核中',value:'in_review'},{label:'已完成',value:'approved'},{label:'全部',value:''}]
const statusText={pending:'待复核',in_review:'复核中',approved:'已通过',rejected:'已驳回'}
const issues=computed(()=>selected.value?.validation_results||[]),errorCount=computed(()=>issues.value.filter(i=>i.level==='error').length),warningCount=computed(()=>issues.value.filter(i=>i.level!=='error').length)
const loadReviews=async()=>{loading.value=true;try{const data=await getReviews(filter.value?{status:filter.value}:{});reviews.value=data.items;if(reviews.value.length)await selectReview(reviews.value[0]);else selected.value=null}catch(e){alert(e.message)}finally{loading.value=false}}
const setFilter=async(value)=>{filter.value=value;await loadReviews()}
const selectReview=async(item)=>{try{selected.value=await getReview(item.id);editableFields.value=JSON.parse(JSON.stringify(selected.value.fields||[]));note.value=selected.value.note||''}catch(e){alert(e.message)}}
const submit=async(action)=>{saving.value=true;try{selected.value=await updateReview(selected.value.id,{fields:editableFields.value,note:note.value,action});editableFields.value=JSON.parse(JSON.stringify(selected.value.fields));alert(action==='approve'?'复核已通过':action==='reject'?'任务已驳回':'复核进度已保存');if(action!=='save')await loadReviews()}catch(e){alert(e.message)}finally{saving.value=false}}
const fieldIssues=(name)=>issues.value.filter(i=>i.field===name),fieldLevel=(name)=>fieldIssues(name).some(i=>i.level==='error')?'has-error':fieldIssues(name).length?'has-warning':''
const confidenceClass=(value)=>value<.65?'low':value<.85?'medium':'high',isLongValue=(value)=>String(value??'').length>80,issueCount=(item)=>(item.validation_results||[]).length
const formatDate=(value)=>value?new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'-'
onMounted(loadReviews)
</script>

<style scoped>
.review-view{display:grid;gap:18px}.page-heading,.review-shell{background:#f8f8f8;border:1px solid #e4e1dc;border-radius:17px;box-shadow:0 8px 24px rgba(0,0,0,.035)}.page-heading{padding:27px 30px;display:flex;justify-content:space-between;align-items:center;background:linear-gradient(135deg,#f9f7f2,#f5ede0);border-color:#e4d6c0}.eyebrow{font:700 11px system-ui;letter-spacing:1.7px;color:#b78a49}h1{font-size:28px;margin:7px 0 5px}.page-heading p{margin:0;color:#918a81;font-size:14px}.heading-count{min-width:100px;height:62px;border-left:1px solid #ded3c2;display:grid;place-content:center;text-align:center}.heading-count strong{font:700 25px system-ui}.heading-count span{color:#9b9388;font-size:12px}.review-shell{min-height:680px;display:grid;grid-template-columns:340px minmax(0,1fr);overflow:hidden}.queue-panel{border-right:1px solid #e5e1db;background:#f5f3ef}.queue-filter{display:flex;gap:6px;padding:15px;border-bottom:1px solid #e5e1db;overflow:auto}.queue-filter button{border:0;background:transparent;padding:7px 10px;border-radius:14px;color:#847d75;white-space:nowrap;cursor:pointer;font-family:inherit}.queue-filter button.active{background:#dfc397;color:#6f4d1e}.queue-state{height:430px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;text-align:center;padding:25px;color:#999}.queue-state strong{color:#625c55}.queue-state small{max-width:220px;line-height:1.7}.state-icon{width:50px;height:50px;border-radius:50%;background:#eee6d9;color:#b68440;display:grid;place-items:center;font:22px system-ui}.review-item{width:100%;min-height:100px;border:0;border-bottom:1px solid #e4e0da;background:#fafafa;display:grid;grid-template-columns:9px 1fr auto;gap:10px;align-items:start;padding:17px;text-align:left;cursor:pointer;font-family:inherit}.review-item:hover,.review-item.selected{background:#fff}.review-item.selected{box-shadow:inset 3px 0 #d5b076}.priority-dot{width:8px;height:8px;margin-top:5px;border-radius:50%;background:#baa}.priority-dot.high{background:#d97969}.review-summary{min-width:0;display:grid;gap:6px}.review-summary strong{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:14px}.review-summary small{color:#8f877f}.review-summary em{font-style:normal;color:#b0a9a1;font-size:11px}.review-status{font-size:11px;color:#a17232}.review-detail{background:#fff;padding:25px;min-width:0}.detail-empty{height:100%;min-height:500px;display:grid;place-content:center;justify-items:center;text-align:center;color:#999}.detail-empty>span{font:42px system-ui;color:#c6a878}.detail-empty strong{font-size:18px;color:#625c55;margin:12px 0 0}.detail-empty p{font-size:13px}.detail-head{display:flex;justify-content:space-between;align-items:flex-start;padding-bottom:17px;border-bottom:1px solid #ece9e4}.breadcrumb{color:#a49c93;font-size:12px}.detail-head h2{font-size:21px;margin:8px 0 0}.status-pill{font-size:12px;padding:6px 11px;border-radius:14px;background:#fff0d8;color:#a86b18}.status-pill.approved{background:#e5f4eb;color:#48805b}.validation-summary{display:flex;align-items:center;gap:22px;margin:18px 0;padding:14px 18px;border-radius:11px;background:#f8f5f0}.validation-summary>div{display:flex;align-items:baseline;gap:5px}.validation-summary strong{font:700 20px system-ui;color:#b57236}.validation-summary span,.validation-summary p{font-size:12px;color:#8b837a}.validation-summary p{margin-left:auto}.field-list{display:grid;gap:13px;max-height:520px;overflow:auto;padding-right:5px}.field-card{border:1px solid #e5e0d9;border-radius:12px;padding:15px;background:#fdfdfd}.field-card.has-error{border-color:#e1a49c}.field-card.has-warning{border-color:#e4c792}.field-top{display:flex;justify-content:space-between;margin-bottom:9px}.field-top label{font-weight:700;font-size:14px}.confidence{font:11px system-ui;padding:4px 8px;border-radius:10px;background:#e5f4eb;color:#48805b}.confidence.medium{background:#fff0d8;color:#a86b18}.confidence.low{background:#fbe5e1;color:#b35f53}.field-card input,.field-card textarea,.note textarea{width:100%;border:1px solid #ddd8d1;border-radius:8px;padding:10px 11px;outline:0;background:#fff;font-family:inherit;font-size:14px}.field-card textarea{min-height:76px;resize:vertical}.evidence{margin-top:10px;padding:10px 12px;border-radius:8px;background:#f4f1ec;display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:start}.evidence span{font-size:11px;color:#a1783e;font-weight:700}.evidence p{margin:0;font-size:12px;line-height:1.6;color:#777068}.evidence small{color:#a49b91}.issue{margin-top:8px;font-size:12px;color:#9b742f}.issue.error{color:#bd6257}.note{display:grid;gap:8px;margin-top:17px;font-size:13px;color:#68615a}.note textarea{min-height:70px;resize:vertical}.detail-actions{display:flex;justify-content:flex-end;gap:10px;padding-top:18px}.detail-actions button{height:40px;padding:0 18px;border-radius:20px;border:0;cursor:pointer;font-family:inherit}.detail-actions button:disabled{opacity:.45;cursor:not-allowed}.reject-btn{background:#f3e3e0;color:#a9564e}.save-btn{background:#eee9e2;color:#625b53}.approve-btn{background:#d5b076;color:#fff}@media(max-width:1050px){.review-shell{grid-template-columns:280px minmax(0,1fr)}}@media(max-width:800px){.review-shell{grid-template-columns:1fr}.queue-panel{border-right:0}.review-detail{min-height:500px}.page-heading{align-items:flex-start}.heading-count{display:none}}
</style>
